// Recorded outputs of FL's Fruity Envelope Controller in the test host (numbers only): per scenario the
// controller values each articulator sent at song ticks. Generated by a script from host runs.
import type { EcArt } from '../../src/model/gen/plugins/envctrl';

export interface GoldenCase {
  name: string;
  /** Factory preset the state starts from; `art0` replaces articulator 1 (and `params` sets parameters) on top of FL's database state. */
  preset?: string;
  art0?: EcArt;
  params?: Record<string, number>;
  /** The "Continuous output" option of the state (fuzz cases). */
  cont?: boolean;
  /** Notes: start (s), length (s), key, velocity, note Mod X, note Mod Y. */
  notes: Array<[number, number, number, number, number, number]>;
  /** Channel Mod X / Y offsets (FL's channel Mod X / Y knobs). */
  chan: [number, number];
  bpm: number;
  /** Parameter automation: time (s), FL parameter index (88 / 89: global X / Y), value. */
  autos: Array<[number, number, number]>;
  tail: number;
  /** The plugin's output changes per articulator: [tick, value] (thinned). */
  host: Record<number, Array<[number, number]>>;
}

